import java.util.Scanner;

public class Main {
    static long getDigitCount(long number) {
        number = (number < 0) ? -number : number;
        long count = 0;
        while (number != 0) {
            ++count;
            number /= 10;
        }
        return count;
    }

    static long makeOnes(long length) {
        long result = 0;
        for (int i = 0; i < length; ++i)
            result = result * 10 + 1;
        return result;
    }

    static long recursiveAux2(long number) {
        if (number == 0) return 0;
        number = (number < 0) ? -number : number;
        long d = getDigitCount(number);
        return d + recursiveAux2(number - makeOnes(d));
    }

    static long recursiveProcess(long n, long s, long acc, long max, int[] state) {
        if (acc >= max) return max;
        if (n == 0) return acc;
        if (n < 0) { n = -n; s = -s; }
        long d = getDigitCount(n);
        long ones_d = makeOnes(d);
        long res1 = max, res2 = max;

        if (0 <= state[(int)d] * s && -10 < state[(int)d] && state[(int)d] < 10) {
            state[(int)d] += s;
            res1 = recursiveProcess(n - ones_d, s, acc + d, max, state);
            state[(int)d] -= s;
        }
        if (0 <= state[(int)(d + 1)] * s && -10 < state[(int)(d + 1)] && state[(int)(d + 1)] < 10) {
            state[(int)(d + 1)] += s;
            res2 = recursiveProcess(n - 10 * ones_d - 1, s, acc + d + 1, res1, state);
            state[(int)(d + 1)] -= s;
        }
        return res1 < res2 ? res1 : res2;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        int[] state = new int[20];
        System.out.println(recursiveProcess(n, 1, 0, recursiveAux2(n), state));
        scanner.close();
    }
}

